#!/usr/bin/env python3
"""Source/body/harness-backed authored transaction editing lessons."""
from lesson_writer import author,CPP

def test(text):
 def result(link):return text+'\n\nThe complete '+link(CPP/'tools/transaction_commands_differential.py','driver')+', '+link(CPP/'support/TransactionCommandsOracle.java','Java oracle')+' and '+link(CPP/'support/transaction_commands.cpp','native harness')+' run sequences against a real TxnDB bound to controlled runtime receivers. After every operation they compare its result, the entire ordered database wire representation and each transaction’s checked-monotonic flag. This detects changes surviving a failed command. Generic exceptions become ERROR; CommandException messages are preserved. The existing '+link(CPP/'build/transaction-commands-differential-results.json','normal report')+' records 1,129 programs, 6,904 operations and zero failures. This guide did not rerun the suite; these totals cover all nine commands together.'
 return result

def add(name,purpose,steps,adaptation,tests,exercise,limits=''):
 author('src/org/minima/system/commands/txn/'+name+'.md',purpose,steps,adaptation,test(tests),exercise,'Full API, exact generic exceptions and node integration parity remain open. These offline draft-transaction tests do not mine, sign or broadcast a transaction. '+limits)
common='C++ obtains the actual shared TxnDB through its runtime lookup and uses existing TxnRow, Transaction and Witness types. The lookup is a runtime dependency boundary; it does not supply full Main startup. '
add('txncreate','Create one named draft transaction with an empty transaction and witness.',
 ['Obtain the custom transaction database before parsing the required id.','Look up id and reject an existing row. The command enforces uniqueness here even though TxnDB.createTransaction itself simply appends.','Create the row, build the common reply and convert the newly looked-up row to JSON.'],common+'It preserves the preflight duplicate check and creation-before-response order.',
 'Cases create new and duplicate IDs, supply missing/blank/non-string IDs, then list or export the database. Multi-command examples stop after a duplicate and reveal whether later commands execute.',
 'Why should the lesson distinguish the command’s duplicate check from the lower-level database method?')
add('txndelete','Delete a named draft transaction, or clear the current list with the exact sentinel all.',
 ['Build the reply and obtain the database, then read id.','If id equals lowercase all, clear the current list and retain found=true. Otherwise call deleteTransaction and use its Boolean result.','Return response:"Deleted" or "Not found". Not finding a row is not a command exception.'],common+'It preserves the exact sentinel spelling and success-shaped not-found reply.',
 'The driver supplies all, ALL, missing and ordinary IDs and issues list/export afterward. Sequences combine multiple inserts, deletion and import to expose ordering changes.',
 'Why does deleting a missing ID differ from listing a missing ID?')
add('txnlist','Display all draft transactions or one named row, optionally omitting witness details.',
 ['Read id with an absent-key default of empty text and read transactiononly with default false. A present blank id still fails Command validation.','For an absent id, iterate the live row list in order and call toJSON(!transactiononly) for each.','For a named id, look up the row and throw Transaction not found if absent.','Return an array for all rows or an object for one row. Row JSON generation can precompute coin IDs.'],common+'It holds the shared row list while iterating and reuses TxnRow.toJSON, including its state effects.',
 'Cases list all/specific/missing rows, toggle transactiononly and compare complete wire state after listing. Random operation sequences expose list ordering after replacement and deletion.',
 'Can a read-looking display command change cached or precomputed transaction data? Follow TxnRow.toJSON.')
add('txnclear','Clear selected witness material and invalidate cached monotonic checking.',
 ['Read id, then scripts/mmr/signatures flags, each defaulting true.','Find the row or throw before mutation.','Always call transaction.clearIsMonotonic, even if all three flags are false.','Clear script proofs, coin proofs and signatures in that order when enabled, then return row JSON.'],common+'Native code explicitly checks nullable transaction/witness values and mutates the existing shared objects rather than replacing the entire row.',
 'The fixture starts with scripts, a coin proof, a signature and a checked-monotonic flag. The driver crosses true/false/TRUE/null flags and exports the result. The separate checked snapshot detects unconditional invalidation when all clearing flags are false.',
 'Why is clearing the validation cache still meaningful when no witness list is cleared?')
add('txnstate','Set a numbered state value on a named draft transaction and recalculate its ID.',
 ['Read id, port and value strings, then find the row.','Parse the port with Integer.parseInt and construct StateVariable from port/value. This supplies its own type and port normalization.','Add the state variable to the transaction, calculateTransactionID, then return the row JSON.'],common+'It reuses javaParseInt for Unicode decimal digits and signed32-bit bounds, rather than a permissive platform parser.',
 'The driver crosses boundary ports including -1,255,256,int extremes, fractions, Unicode digits and overflow with numeric/Boolean/HEX/string/malformed values. Each case then lists the row and compares database bytes.',
 'Which validation belongs to Integer.parseInt and which belongs to StateVariable? Use port256 as an example.')
add('txnexport','Serialize a stored draft transaction to HEX or a file.',
 ['Read id and showtxn and require the row.','If file is present, resolve it, attempt to delete an existing destination, then serialize the row to the file. Return absolute path and formatted size.','Otherwise serialize the row to bytes first, optionally call toJSON for the displayed transaction, and return the previously captured data bytes.'],common+'It reuses MiniFile and MiniFormat. The ordering of serialization before optional JSON is retained because row JSON can precompute coin IDs.',
 'The driver exports Java-generated rows to HEX and files, reads files back with txnview/import and toggles showtxn. It compares command responses and the database state after each operation.',
 'Why must an implementation avoid silently moving row.toJSON before the byte serialization?',
 'File permission, interrupted writes and every filesystem failure are not covered by these round trips.')
add('txnimport','Decode a serialized row, optionally rename it, and insert it into the draft database.',
 ['Obtain the database. If file is present, choose it ahead of data, require its existence and read its bytes. Otherwise require data and decode it through Command.','Convert bytes to TxnRow. If id is present, apply it to the decoded row.','Call addCompleteTransaction, which removes matching IDs and appends the imported row.','Return its JSON; failures during response construction can occur after insertion.'],common+'It preserves file precedence and uses the shared row decoder. Missing decoded rows currently become generic native errors, whose exact class is not compared in this suite.',
 'The driver imports valid, appended, truncated and malformed Java-produced row bytes, tests explicit renaming and duplicate IDs, and provides file and data together. Follow-up export/list reveals changes already made before an error.',
 'Why should a failed import response not automatically imply the database is unchanged?')
add('txnview','Decode and display serialized transaction data without inserting it into TxnDB.',
 ['Choose file ahead of data, require a file to exist when selected, and decode a TxnRow.','Only the data branch honors an id parameter if it is directly present. The advertised valid-parameter list does not include id.','Return row JSON without adding the row to the database.'],
 'C++ reuses the same row decoder and file helpers as txnimport but does not obtain a database owner. It retains the source’s data-only renaming branch even though CommandRunner may reject id before reaching it.',
 'The fixture invokes commands both directly and through CommandRunner. Direct txnview cases supply id with data, while dispatcher sequences test parameter filtering. Wire snapshots verify that viewing does not insert a row.',
 'Why can direct runCommand and a command string expose different behavior for the same extra parameter?')
add('txnoutput','Append a coin output, using token metadata to convert displayed amounts into stored amounts.',
 ['Read id, amount, address and storestate. Default the token ID to Minima; when another token ID is supplied, look up its metadata and reject an unknown token.','For an attached token, convert the requested token amount through getScaledMinimaAmount; otherwise retain the amount.','Construct the output coin with the output placeholder ID and optional Token metadata before looking up the draft row.','Append the coin, precompute transaction output IDs, recalculate the transaction ID and return row JSON.'],common+'The implementation reuses Coin, Token and TxPoWGenerator, so it does not duplicate ID derivation or scaling.',
 'Cases cross negative/zero/fractional/extreme amounts with valid and malformed addresses. Java-generated imported tokens exercise scaling and keep-state flags. Unknown token IDs, missing rows and follow-up exports expose error ordering and mutations.',
 'If both the token ID and transaction ID are missing, which error should appear first? Follow the actual lookup order.')

# The database pair has its own full fixture/driver evidence.
def dbtest(text):
 def result(link):return text+'\n\nThe complete '+link(CPP/'tools/txndb_differential.py','TxnDB driver')+', '+link(CPP/'support/TxnDBOracle.java','Java oracle')+' and '+link(CPP/'support/txndb.cpp','native harness')+' compare source-derived serialized fixtures, partial byte consumption and persistent operation sequences. The existing '+link(CPP/'build/txndb-differential-results.json','normal report')+' records 2,503 programs passed and zero failures. I/O failures and other exceptions are distinguished only as IO_ERROR versus ERROR, so fine-grained error text/classes and logger behavior are not established. No test was rerun for this guide.'
 return result

author('src/org/minima/database/userprefs/txndb/TxnDB.md','Manage the ordered list of named draft transaction rows and persist its serialized form through UserDB.',
 ['createTransaction appends a fresh row without checking duplicate IDs. addCompleteTransaction instead deletes every matching ID, then appends the supplied row.','getTransactionRow returns the first matching row. deleteTransaction constructs and replaces the list object, retaining only nonmatching rows; held references to the old list remain distinct. clearTxns clears the current list in place.','saveDB serializes into UserDB. loadDB skips the zero sentinel; otherwise it decodes another database and replaces the current list with the decoded list.','Wire output writes a MiniNumber row count followed by rows. Reading immediately installs a fresh list, reads the count and appends rows one by one, so truncation can leave a partial list.','The conversion helper catches IOException, logs it and returns null; it does not catch arbitrary runtime exceptions.'],
 'C++ uses a shared vector of shared TxnRow pointers to reproduce list replacement versus in-place clear. It retains the UserDB owner/resolver boundary and uses the existing bounded wire decoders. Conversion logging still uses a legacy clog message, so logger parity remains open.',
 dbtest('The driver generates30 Java row/database fixtures, adds trailing bytes and many truncations, and compares conversion versus in-place reads. Its125 seeded50-operation sequences retain list/row aliases, rename/reinsert rows, mutate held lists and save/load preference bytes. Observations include current IDs, held-list IDs and row contents.'),
 'Hold listTxns(), then delete a row and then clearTxns(). Which list does each operation change?',
 'Full mutable-list/container APIs, exact error/logger behavior and node lifecycle integration remain incomplete. Preference-byte persistence here is not a native H2 database engine.')
author('src/org/minima/database/userprefs/txndb/TxnRow.md','Keep a draft transaction ID, its Transaction and its Witness as one serializable record.',
 ['Store the ID and object references. setID renames the same row; clearWitness replaces its Witness object rather than clearing the old object in place.','toJSON first includes id and precomputes transaction coin IDs, then serializes the transaction. When showWitness is true, include witness JSON and serialized output coins.','Write fields in order: MiniString ID, Transaction, Witness.','Read ID first, replace/read a new Transaction next, and only then replace/read a new Witness. If transaction reading fails, the old witness can still remain.','The convenience conversion catches IOException and returns null after logging; direct read exposes partial state.'],
 'C++ uses optional ID plus shared transaction/witness ownership and sequential replacement in readDataStream. It preserves JSON’s coin-ID side effect and showWitness behavior. The convenience helper’s legacy logger output remains a known difference.',
 dbtest('The fixtures compare complete and partial row reads, byte offsets, prior transaction/witness state, showWitness variants, row renaming and clearWitness. The same records feed offline command import/export cases, linking the wire representation to user operations.'),
 'At a truncation halfway through Transaction, which fields have been replaced and which can still refer to the old objects?',
 'Complete generic exception, logger, public reference-mutation and stream-overload parity remain open; successful round trips alone do not establish them.')
print('Authored9transactioncommand and2database lessons.')
